-- 业务表及外键；不插入客户、场所或预约。
create table clean_customer (id bigint auto_increment primary key, department_id bigint not null, account_id bigint unique, name varchar(180) not null, contact varchar(180) not null, billing_type varchar(20) not null, enabled boolean not null, version bigint not null);
create table clean_site (id bigint auto_increment primary key, customer_id bigint not null, name varchar(180) not null, address varchar(500) not null, contact varchar(180) not null, instructions varchar(1000) not null, enabled boolean not null, version bigint not null);
create table service_rate (id bigint auto_increment primary key, department_id bigint not null, name varchar(180) not null, name_en varchar(180) not null, category_code varchar(20) not null, unit varchar(20) not null, base_price decimal(14,2) not null, unit_price decimal(14,2) not null, minutes_per_unit int not null, workers_required int not null, enabled boolean not null, version bigint not null);
create table service_extra (id bigint auto_increment primary key, department_id bigint not null, name varchar(180) not null, name_en varchar(180) not null, price decimal(14,2) not null, minutes int not null, enabled boolean not null, version bigint not null);
create table clean_worker (id bigint auto_increment primary key, department_id bigint not null, account_id bigint not null unique, name varchar(180) not null, hourly_rate decimal(14,2) not null, enabled boolean not null, version bigint not null);
create table worker_availability (id bigint auto_increment primary key, worker_id bigint not null, weekday int not null, start_time varchar(5) not null, end_time varchar(5) not null, version bigint not null);
create table worker_time_off (id bigint auto_increment primary key, worker_id bigint not null, starts_at timestamp(6) not null, ends_at timestamp(6) not null, reason varchar(500) not null, enabled boolean not null, version bigint not null);
create table clean_booking (id bigint auto_increment primary key, department_id bigint not null, customer_id bigint not null, site_id bigint not null, service_id bigint not null, service_name varchar(180) not null, unit varchar(20) not null, units decimal(14,2) not null, extras_snapshot varchar(4000) not null, site_snapshot varchar(2000) not null, status varchar(24) not null, occurrences int not null, interval_weeks int not null, duration_minutes int not null, workers_required int not null, unit_visit_price decimal(14,2) not null, discount decimal(14,2) not null, quote_note varchar(1000) not null, created_at timestamp(6) not null, confirmed_at timestamp(6), version bigint not null);
create table clean_visit (id bigint auto_increment primary key, booking_id bigint not null, occurrence_no int not null, starts_at timestamp(6) not null, ends_at timestamp(6) not null, status varchar(24) not null, round_no int not null, charge decimal(14,2) not null, note varchar(1000) not null, version bigint not null);
create table work_round (id bigint auto_increment primary key, visit_id bigint not null, round_no int not null, leader_id bigint not null, starts_at timestamp(6) not null, ends_at timestamp(6) not null, status varchar(24) not null, started_at timestamp(6), completed_at timestamp(6), completion_note varchar(1000) not null, acceptance_note varchar(1000) not null);
create table work_assignment (id bigint auto_increment primary key, round_id bigint not null, worker_id bigint not null, hourly_rate decimal(14,2) not null, actual_minutes int not null, cost decimal(14,2) not null, settlement_id bigint);
create table work_photo (id bigint auto_increment primary key, round_id bigint not null, uploader_id bigint not null, phase varchar(12) not null, file_name varchar(80) not null unique, sha256 varchar(64) not null, caption varchar(300) not null, size bigint not null, created_at timestamp(6) not null);
create table money_entry (id bigint auto_increment primary key, visit_id bigint not null, department_id bigint not null, kind varchar(12) not null, amount decimal(14,2) not null, reference varchar(120) not null, note varchar(500) not null, actor varchar(60) not null, created_at timestamp(6) not null);
create table worker_settlement (id bigint auto_increment primary key, worker_id bigint not null, department_id bigint not null, from_date varchar(10) not null, to_date varchar(10) not null, amount decimal(14,2) not null, status varchar(24) not null, payment_reference varchar(120), note varchar(500) not null, created_at timestamp(6) not null, confirmed_at timestamp(6), paid_at timestamp(6), version bigint not null);
create table visit_event (id bigint auto_increment primary key, visit_id bigint not null, action varchar(40) not null, note varchar(1000) not null, actor varchar(120) not null, created_at timestamp(6) not null);
create table command_receipt (id bigint auto_increment primary key, account_id bigint not null, request_key varchar(36) not null, action varchar(120) not null, fingerprint varchar(64) not null, result_json longtext not null, created_at timestamp(6) not null);
alter table clean_customer add foreign key (department_id) references department(id);
alter table clean_customer add foreign key (account_id) references account(id);
alter table clean_site add foreign key (customer_id) references clean_customer(id);
alter table service_rate add foreign key (department_id) references department(id);
alter table service_extra add foreign key (department_id) references department(id);
alter table clean_worker add foreign key (department_id) references department(id);
alter table clean_worker add foreign key (account_id) references account(id);
alter table worker_availability add foreign key (worker_id) references clean_worker(id);
alter table worker_time_off add foreign key (worker_id) references clean_worker(id);
alter table clean_booking add foreign key (department_id) references department(id);
alter table clean_booking add foreign key (customer_id) references clean_customer(id);
alter table clean_booking add foreign key (site_id) references clean_site(id);
alter table clean_booking add foreign key (service_id) references service_rate(id);
alter table clean_visit add foreign key (booking_id) references clean_booking(id);
alter table work_round add foreign key (visit_id) references clean_visit(id);
alter table work_round add foreign key (leader_id) references clean_worker(id);
alter table work_assignment add foreign key (round_id) references work_round(id);
alter table work_assignment add foreign key (worker_id) references clean_worker(id);
alter table work_assignment add foreign key (settlement_id) references worker_settlement(id);
alter table work_photo add foreign key (round_id) references work_round(id);
alter table work_photo add foreign key (uploader_id) references account(id);
alter table money_entry add foreign key (visit_id) references clean_visit(id);
alter table money_entry add foreign key (department_id) references department(id);
alter table worker_settlement add foreign key (worker_id) references clean_worker(id);
alter table worker_settlement add foreign key (department_id) references department(id);
alter table visit_event add foreign key (visit_id) references clean_visit(id);
alter table command_receipt add foreign key (account_id) references account(id);
create unique index uq_visit_occurrence on clean_visit(booking_id,occurrence_no);
create unique index uq_work_round on work_round(visit_id,round_no);
create unique index uq_round_worker on work_assignment(round_id,worker_id);
create unique index uq_money_reference on money_entry(department_id,reference);
create unique index uq_command_actor_key on command_receipt(account_id,request_key);
create unique index uq_photo_digest on work_photo(round_id,phase,sha256);
create index ix_visit_time on clean_visit(starts_at,status);
create index ix_assignment_worker on work_assignment(worker_id,round_id);
create index ix_booking_customer on clean_booking(customer_id,created_at);
create table photo_data (photo_id bigint primary key, content longblob not null, foreign key(photo_id) references work_photo(id));
